def _ua9_sobrat_katalog():
    import stranica as _ua9_s
    spisok = _ua9_s.mashiny()
    kadry = {}
    for mashina in spisok:
        nom = _ua9_s.nomer(mashina)
        kadry[nom] = _ua9_s.kadry_mashiny(mashina)
    katalog = _ua9_s.sobrat_katalog(spisok, kadry)
    try:
        import master_card as _ua9_m
        katalog = _ua9_m.obrabotat_obshuyu(katalog)
    except Exception:
        pass
    return katalog, spisok

