def _publish_locked(
    base_publish: Callable[..., Any], codes: list[str], proba: bool = False
) -> tuple[bool, str, dict[str, Any]]:
    codes = [_code(value) for value in codes]
    if not codes or len(codes) != len(set(codes)):
        raise PublishError("TARGET_SET_INVALID")
    snapshot = Snapshot(codes)
    before_rows, before_db = _row_map()
    missing = [code for code in codes if code not in before_rows]
    if missing:
        raise PublishError("TARGETS_NOT_PUBLISHED:" + ",".join(missing))
    protected = _protected_pages(set(codes))
    evidence: dict[str, Any] = {
        "contract_id": CONTRACT_ID,
        "codes": codes,
        "mode": "PROBE" if proba else "INSTALL",
        "backup_root": str(snapshot.root),
        "published_rows_sha256_before": before_db,
        "staged_diagnostics": {},
        "base_results": {},
        "catalog": None,
        "verification": None,
        "rollback": None,
    }
    try:
        evidence["staged_diagnostics"] = _stage_diags(codes)
        for code in codes:
            ok, message = _call_base(base_publish, code, proba)
            evidence["base_results"][code] = {"ok": ok, "message": message[:2000]}
            if not ok:
                raise PublishError("BASE_PUBLISH_FAILED:%s:%s" % (code, message[:500]))

        catalog_source, catalog_rows = _build_catalog()
        generated_ids = {str(row.get("auto_number") or "").upper() for row in catalog_rows}
        if generated_ids != set(before_rows):
            raise PublishError("CATALOG_ROW_SET_MISMATCH")
        _validate_catalog(catalog_source, before_rows)

        if proba:
            evidence["rollback"] = snapshot.restore()
            evidence["status"] = "PASS"
            return True, "Проба публикации прошла; production-файлы не изменены.", evidence

        evidence["catalog"] = _install_catalog(catalog_source, codes[-1])
        after_rows, after_db = _row_map()
        if before_db != after_db or set(before_rows) != set(after_rows):
            raise PublishError("CRM_ROWS_CHANGED_DURING_PUBLICATION")
        if _protected_pages(set(codes)) != protected:
            raise PublishError("PROTECTED_PAGE_CHANGED")
        evidence["verification"] = _verify_bundle(codes)
        evidence["published_rows_sha256_after"] = after_db
        evidence["status"] = "PASS"
        _append_log("PASS %s backup=%s" % (",".join(codes), snapshot.root))
        return True, (
            "Страницы, диагностика и оба каталога опубликованы одним проверенным пакетом: "
            + ", ".join(codes)
        ), evidence
    except Exception as exc:
        try:
            evidence["rollback"] = snapshot.restore()
        except Exception as rollback_exc:
            evidence["rollback_error"] = type(rollback_exc).__name__ + ":" + str(rollback_exc)
            _append_log("CRITICAL ROLLBACK FAIL %s %s" % (",".join(codes), rollback_exc))
            raise
        evidence["status"] = "FAIL"
        evidence["error"] = type(exc).__name__ + ":" + str(exc)
        _append_log("FAIL %s %s rollback=PASS" % (",".join(codes), evidence["error"]))
        return False, "Публикация отменена: %s. Выполнен полный откат." % str(exc), evidence

snapshot.source:
def snapshot():
    from ua_delivery_status import public_status
    conn = sqlite3.connect((ROOT / 'crm.db').as_uri() + '?mode=ro', uri=True, timeout=5)
    conn.row_factory = sqlite3.Row
    try:
        rows = [dict(r) for r in conn.execute('SELECT * FROM cars WHERE published=1')]
    finally:
        conn.close()
    result = {}
    codes = set()
    for row in rows:
        code = str(row.get('auto_number') or '')
        if not code or code in codes:
            raise RuntimeError('Missing or duplicate published auto_number')
        codes.add(code)
        raw = json.dumps(row, sort_keys=True, ensure_ascii=False, default=str).encode()
        result[str(row['id'])] = {'code': code, 'sha256': hashlib.sha256(raw).hexdigest(), 'delivery_status': public_status(row.get('status'))}
    return result

reconcile_once.source:
def reconcile_once(publish=None, clock=time.time):
    with open(LOCK, 'a') as lock:
        os.chmod(LOCK, 0o600)
        try:
            fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError:
            return 'busy'
        with STATE.open() as source:
            state = json.load(source)
        if state.get('version') != 1:
            raise RuntimeError('Unsupported sync state')
        rows = snapshot()
        retry = state.setdefault('retry', {})
        for identity, revision in rows.items():
            if revision['sha256'] == state['revisions'].get(identity, {}).get('sha256'):
                continue
            attempt = retry.get(identity, {})
            if attempt.get('sha256') == revision['sha256'] and attempt.get('after', 0) > clock():
                continue
            try:
                if revision['delivery_status'] == 'hidden':
                    from ua_stage_catalog_sync import reconcile
                    reconcile(apply=True)
                else:
                    if publish is None:
                        from publikaciya import opublikovat
                        publish = opublikovat
                    ok, message = publish(revision['code'])
                    if not ok:
                        raise RuntimeError(str(message)[:500])
                    from ua_public_freshness import verify_public
                    verify_public(revision['code'])
                if snapshot().get(identity) != revision:
                    # Keep old ledger revision: a newer operator edit needs another pass.
                    LOG.warning('CRM sync: changed during publish: %s', revision['code'])
                    return 'changed_during_publish'
                state['revisions'][identity] = revision
                retry.pop(identity, None)
                state['last_success'] = {'code': revision['code'], 'at': clock()}
                save_state(state)
                LOG.info('CRM sync PASS: %s', revision['code'])
                return 'hidden' if revision['delivery_status'] == 'hidden' else 'published'
            except Exception as exc:
                count = (attempt.get('count', 0) if attempt.get('sha256') == revision['sha256'] else 0) + 1
                retry[identity] = {'sha256': revision['sha256'], 'count': count,
                                   'after': clock() + min(300, 15 * 2 ** min(count-1, 5)),
                                   'error': type(exc).__name__ + ': ' + str(exc)[:500]}
                save_state(state)
                LOG.exception('CRM sync failed; retry pending: %s', revision['code'])
                # Continue so a failing card does not starve other pending cards.
        return 'idle'
